#4 New stems say per real hour explicitly; original day/hour conflict is preserved.
def fmt(t):
    h,m=divmod(t,60)
    return '자정'if t==0 else f'{"오전"if h<12 else"낮"if h==12 else"오후"}{h if h<=12 else h-12}시{m:02d}분'
for loss,elapsed in [(10,180),(12,240),(15,300),(20,180),(25,240)]:
    shown=F(elapsed*(60-loss),60);assert shown.denominator==1;end=480+int(shown)
    add(4,'low',dict(loss=loss,realElapsed=elapsed,setting=480),f'실제1시간마다{loss}분씩 늦어지는 시계를 오전8시에 정확히 맞췄습니다. 실제로{elapsed}분이 지난 순간 이 시계가 가리키는 시각을 구하시오.',[end//60,end%60],['시','분'],[f'실제60분 동안 시계는60−{loss}＝{60-loss}분만 갑니다.',f'실제{elapsed}분은{elapsed//60}시간이므로 시계가 간 시간은{60-loss}×{elapsed//60}＝{int(shown)}분입니다.',f'오전8시에서{int(shown)}분 뒤이므로{fmt(end)}입니다.'],'실제 경과 시간에서 느린 시계의 표시 시간을 정방향 계산하기','forward exact slow-clock rate')
for loss,observed,setting in [(10,660,480),(12,672,432),(15,720,420),(20,700,520),(25,710,470)]:
    elapsed=observed-setting;error=elapsed*loss//60;display=observed-error
    add(4,'middle',dict(loss=loss,realObserved=observed,displayObserved=display),f'실제1시간마다{loss}분씩 늦어지는 시계를 그날 오전에 한 번 정확히 맞춰 놓았습니다. 정확한 시각이{fmt(observed)}인 순간 이 시계는{fmt(display)}을 가리켰습니다. 정확히 맞춰 놓았던 시각을 구하시오.',[setting//60,setting%60],['시','분'],[f'같은 순간 실제 시각과 표시 시각의 차는{error}분입니다. 이 차는 처음 정확히 맞춘 뒤 쌓인 늦음입니다.',f'실제1시간마다{loss}분씩 늦으므로 지난 시간은{error}÷{loss}＝{elapsed//60}시간입니다.',f'정확한 관측 시각{fmt(observed)}에서{elapsed//60}시간을 거슬러 가면{fmt(setting)}입니다.'],'동시 관측한 실제·표시 시각의 오차로 처음 맞춘 시각을 역산하기','clock-error accumulation and unknown correct setting')
for setting,elapsed,gain,loss in [(300,360,5,10),(240,420,6,15),(120,480,10,20),(60,540,12,25),(0,600,12,30)]:
    a=setting+elapsed*(60+gain)//60;b=setting+elapsed*(60-loss)//60
    add(4,'high',dict(setting=setting,fastGain=gain,fastDisplay=a,slowDisplay=b),f'시계A와B를{fmt(setting)}에 같은 정확한 시각으로 맞췄습니다. A는 실제1시간마다{gain}분씩 빨라지고,B는 일정한 비율로 느려집니다. 그날 같은 순간 A는{fmt(a)},B는{fmt(b)}을 가리켰습니다. 실제로 지난 시간과 B가 실제1시간마다 늦어지는 시간을 각각 분으로 구하시오.',[elapsed,loss],['실제 경과(분)','B의 시간당 늦음(분)'],[f'A의 표시 차는{a-setting}분입니다. 실제60분 동안 A는{60+gain}분 가므로 실제 시간은{a-setting}÷{60+gain}×60＝{elapsed}분입니다.',f'이는{elapsed//60}시간입니다. B는 그동안{b-setting}분 갔으므로 실제보다{elapsed-(b-setting)}분 덜 갔습니다.',f'한 시간마다 늦는 양은{elapsed-(b-setting)}÷{elapsed//60}＝{loss}분입니다. 실제 경과 시간과 시계가 가리킨 시각을 구분해야 합니다.'],'동시 관측한 빠른 시계로 실제 시간을 먼저 찾고 느린 시계의 속도를 역산하기','two clock rates with one unknown loss')

#5 Preserve the displayed unreduced descending fractions.
def pos(d,a):return (d-2)*(d-1)//2+d-a
base5=['분모가2·3·4·…인 묶음의 길이는1·2·3·…입니다. 같은 분모 안에서 분자는 큰 수부터1까지 줄어듭니다.']
for d,a in [(8,3),(9,4),(10,3),(11,7),(12,5)]:
    first=pos(d,a);second=pos(2*d,2*a);answer=second-first
    add(5,'middle',dict(denominator=d,numerator=a,comparisonDenominator=2*d,comparisonNumerator=2*a),f'다음 배열에서 약분 전 분모가{d},분자가{a}인 항과 분모가{2*d},분자가{2*a}인 항의 위치 차를 구하시오.',[answer],['위치 차'],base5+[f'첫 항의 앞선 묶음 개수는{(d-2)*(d-1)//2}개이고 묶음 안{d-a}번째이므로{first}번째입니다.',f'둘째 항의 앞선 묶음 개수는{(2*d-2)*(2*d-1)//2}개이고 묶음 안{2*d-2*a}번째이므로{second}번째입니다.',f'위치 차는{second}−{first}＝{answer}입니다. 값이 같아도 약분 전 표시가 달라 배열의 위치는 다릅니다.'],'같은 값의 서로 다른 표시 항을 두 묶음에서 각각 찾아 비교하기','two raw representations and group-position difference')
